import{_ as a,o,c as l,ag as n}from"./chunks/framework.1IVNT0ce.js";const m=JSON.parse('{"title":"API Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md"}'),s={name:"reference/api.md"};function r(i,e,t,c,d,p){return o(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>This page summarizes the public API that Klix exports from <code>klix.__init__</code>.</p><p>For conceptual explanations, start with <a href="./../concepts/architecture">Architecture</a>. For usage-oriented walkthroughs, see the pages under <a href="./../getting-started">Guides</a>.</p><h2 id="core-types" tabindex="-1">Core Types <a class="header-anchor" href="#core-types" aria-label="Permalink to &quot;Core Types&quot;">​</a></h2><h3 id="app" tabindex="-1"><code>App</code> <a class="header-anchor" href="#app" aria-label="Permalink to &quot;`App`&quot;">​</a></h3><p>The main framework entry point.</p><p>Use it to:</p><ul><li>register commands</li><li>register middleware</li><li>register lifecycle event handlers</li><li>configure theme and persistence</li><li>start the runtime loop</li></ul><p>Common methods and decorators:</p><ul><li><code>command(...)</code></li><li><code>middleware(...)</code></li><li><code>on(...)</code></li><li><code>add_completer(...)</code></li><li><code>generate_help()</code></li><li><code>run()</code></li></ul><p>See <a href="./../concepts/app">App</a>.</p><h3 id="appconfig" tabindex="-1"><code>AppConfig</code> <a class="header-anchor" href="#appconfig" aria-label="Permalink to &quot;`AppConfig`&quot;">​</a></h3><p>Dataclass carrying high-level app configuration fields such as:</p><ul><li><code>name</code></li><li><code>version</code></li><li><code>description</code></li><li><code>theme</code></li><li><code>persist_session</code></li><li><code>session_id</code></li><li><code>state_schema</code></li></ul><p>See <a href="./config">Reference: Config</a>.</p><h3 id="session" tabindex="-1"><code>Session</code> <a class="header-anchor" href="#session" aria-label="Permalink to &quot;`Session`&quot;">​</a></h3><p>The per-run execution context.</p><p>Important attributes:</p><ul><li><code>id</code></li><li><code>state</code></li><li><code>metadata</code></li><li><code>ui</code></li><li><code>input_engine</code></li><li><code>history</code></li></ul><p>Important method:</p><ul><li><code>create_task(coro)</code></li></ul><p>See <a href="./../concepts/session">Session</a>.</p><h3 id="sessionstate" tabindex="-1"><code>SessionState</code> <a class="header-anchor" href="#sessionstate" aria-label="Permalink to &quot;`SessionState`&quot;">​</a></h3><p>Base dataclass-like marker used for typed session state. Extend it with your own dataclass model.</p><h3 id="terminalmetadata" tabindex="-1"><code>TerminalMetadata</code> <a class="header-anchor" href="#terminalmetadata" aria-label="Permalink to &quot;`TerminalMetadata`&quot;">​</a></h3><p>Structured snapshot of terminal-related metadata created when the session starts.</p><p>Fields include:</p><ul><li><code>platform</code></li><li><code>python_version</code></li><li><code>terminal</code></li><li><code>terminal_size</code></li><li><code>is_tty</code></li><li><code>cwd</code></li></ul><h2 id="commands-and-routing" tabindex="-1">Commands And Routing <a class="header-anchor" href="#commands-and-routing" aria-label="Permalink to &quot;Commands And Routing&quot;">​</a></h2><h3 id="command" tabindex="-1"><code>Command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;`Command`&quot;">​</a></h3><p>Registration-time container for:</p><ul><li>command name</li><li>handler</li><li>help text</li><li>aliases</li><li>optional argument schema</li></ul><h3 id="parsedcommand" tabindex="-1"><code>ParsedCommand</code> <a class="header-anchor" href="#parsedcommand" aria-label="Permalink to &quot;`ParsedCommand`&quot;">​</a></h3><p>Result of routing and argument validation.</p><p>Fields:</p><ul><li><code>name</code></li><li><code>args</code></li><li><code>raw_input</code></li></ul><p>See <a href="./commands">Reference: Commands</a>.</p><h2 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h2><h3 id="middlewarecontext" tabindex="-1"><code>MiddlewareContext</code> <a class="header-anchor" href="#middlewarecontext" aria-label="Permalink to &quot;`MiddlewareContext`&quot;">​</a></h3><p>Carries the active command execution context through middleware.</p><p>Fields:</p><ul><li><code>raw_input</code></li><li><code>session</code></li><li><code>command</code></li><li><code>cancelled</code></li></ul><h3 id="nextfn" tabindex="-1"><code>NextFn</code> <a class="header-anchor" href="#nextfn" aria-label="Permalink to &quot;`NextFn`&quot;">​</a></h3><p>Callable type for the middleware continuation.</p><p>See <a href="./middleware">Reference: Middleware</a>.</p><h2 id="ui-and-rendering" tabindex="-1">UI And Rendering <a class="header-anchor" href="#ui-and-rendering" aria-label="Permalink to &quot;UI And Rendering&quot;">​</a></h2><h3 id="themeconfig" tabindex="-1"><code>ThemeConfig</code> <a class="header-anchor" href="#themeconfig" aria-label="Permalink to &quot;`ThemeConfig`&quot;">​</a></h3><p>Semantic color configuration used by renderers and widgets.</p><h3 id="cursorcontrol" tabindex="-1"><code>CursorControl</code> <a class="header-anchor" href="#cursorcontrol" aria-label="Permalink to &quot;`CursorControl`&quot;">​</a></h3><p>Small helper for terminal cursor operations used by the UI and layout system.</p><h3 id="inputmode" tabindex="-1"><code>InputMode</code> <a class="header-anchor" href="#inputmode" aria-label="Permalink to &quot;`InputMode`&quot;">​</a></h3><p>Prompt behavior enum used by the input engine and input components.</p><p>Values:</p><ul><li><code>COMMAND</code></li><li><code>TEXT</code></li><li><code>MULTILINE</code></li><li><code>CONFIRM</code></li><li><code>PASSWORD</code></li></ul><h3 id="helpgenerator" tabindex="-1"><code>HelpGenerator</code> <a class="header-anchor" href="#helpgenerator" aria-label="Permalink to &quot;`HelpGenerator`&quot;">​</a></h3><p>Utility that formats registered commands into a help string.</p><h3 id="cliargsparser" tabindex="-1"><code>CLIArgsParser</code> <a class="header-anchor" href="#cliargsparser" aria-label="Permalink to &quot;`CLIArgsParser`&quot;">​</a></h3><p>Wrapper around <code>argparse.ArgumentParser</code> used for app-level CLI flags like <code>--version</code>, <code>--config</code>, and <code>--debug</code>.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><h3 id="sessionstatemanager" tabindex="-1"><code>SessionStateManager</code> <a class="header-anchor" href="#sessionstatemanager" aria-label="Permalink to &quot;`SessionStateManager`&quot;">​</a></h3><p>Handles serialization and storage of session state when persistence is enabled.</p><h2 id="error-types" tabindex="-1">Error Types <a class="header-anchor" href="#error-types" aria-label="Permalink to &quot;Error Types&quot;">​</a></h2><p>Klix exports:</p><ul><li><code>KlixError</code></li><li><code>CommandNotFoundError</code></li><li><code>ArgValidationError</code></li><li><code>InputCancelledError</code></li><li><code>SessionStateError</code></li><li><code>MiddlewareAbortError</code></li><li><code>RenderError</code></li><li><code>CompatibilityError</code></li></ul><p>See <a href="./errors">Reference: Errors</a>.</p><h2 id="example-import-block" tabindex="-1">Example Import Block <a class="header-anchor" href="#example-import-block" aria-label="Permalink to &quot;Example Import Block&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> klix</span></span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">dataclass</span></span>\n<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> DemoState</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">SessionState</span><span style="color:#89DDFF;">):</span></span>\n<span class="line"><span style="color:#BABED8;">    counter</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> int</span><span style="color:#89DDFF;"> =</span><span style="color:#F78C6C;"> 0</span></span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line"><span style="color:#BABED8;">app </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">App</span><span style="color:#89DDFF;">(</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Demo</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    version</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">0.1.0</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">API reference example</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#BABED8;font-style:italic;">    state_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">DemoState</span><span style="color:#89DDFF;">,</span></span>\n<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Importing internal modules directly when the public API already exports what you need.</li><li>Treating internal helpers like <code>_router</code> and <code>_event_bus</code> as stable public APIs. They are useful in advanced examples, but they are not the main supported surface.</li><li>Assuming everything in the package is exported from <code>klix.__init__</code>. Check the list above first.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./config">Reference: Config</a></li><li><a href="./errors">Reference: Errors</a></li><li><a href="./../examples/minimal">Examples: Minimal</a></li></ul>',71)])])}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
